create table if not exists public.workspace_integrations (workspace_id uuid not null references public.workspaces(id) on delete cascade, integration_key text not null, provider text not null default 'composio', status text not null default 'not_connected' check(status in ('connected','not_connected','error')), account_label text, provider_connection_ref text, metadata jsonb not null default '{}', connected_at timestamptz, updated_at timestamptz not null default now(), primary key(workspace_id,integration_key)); alter table public.workspace_integrations enable row level security; drop policy if exists workspace_integrations_member_read on public.workspace_integrations; create policy workspace_integrations_member_read on public.workspace_integrations for select to authenticated using(public.is_curatia_member(workspace_id)); insert into public.workspace_integrations(workspace_id,integration_key,status,account_label,provider_connection_ref,connected_at) select w.id,x.key,'connected',x.label,x.ref,now() from public.workspaces w cross join (values ('gmail','Gmail','gmail_attire-tetric'),('googledrive','Google Drive','googledrive_doffer-esth'),('github','GitHub','github_cosse-aurir'),('linkedin','LinkedIn','linkedin_bizet-assert')) as x(key,label,ref) where w.slug='curatia' on conflict(workspace_id,integration_key) do update set status=excluded.status,account_label=excluded.account_label,provider_connection_ref=excluded.provider_connection_ref,connected_at=coalesce(public.workspace_integrations.connected_at,excluded.connected_at),updated_at=now(); insert into public.workspace_integrations(workspace_id,integration_key,status,account_label) select id,'metricool','not_connected','Metricool' from public.workspaces where slug='curatia' on conflict(workspace_id,integration_key) do nothing;
